  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': 'Avance por uma faixa de repetições com o mesmo peso. Ao atingir o topo da faixa em todas as séries, o peso aumenta e as repetições voltam ao mínimo.',
  'Nothing logged yet, so this session sets the baseline.': 'Nada registrado ainda, então esta sessão define o ponto de partida.',
  'Reminds you at this time on days that have a routine planned.': 'Lembra você neste horário nos dias em que há uma rotina planejada.',
  'Each profile keeps its own plan, workouts & body weight.': 'Cada perfil mantém seu próprio plano, seus treinos e seu peso corporal.',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': '{0} sessões seguidas abaixo da meta. Reduza para {1} s e vá subindo de novo.',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': 'Topo da faixa de repetições em todas as séries. Mais {0} {1}, de volta a {2} repetições.',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': 'Repetições não concluídas em {0} sessões seguidas. Volte para {1} {2} e vá subindo de novo.',
  'Missed reps. Reset to {0} {1} and work back up.': 'Repetições não concluídas. Volte para {0} {1} e vá subindo de novo.',
  'Missed reps last time. Same weight again ({0} of {1} to go).': 'Faltaram repetições da última vez. Mesmo peso de novo (faltam {0} de {1}).',
  '{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.': '{0} séries trazem um {1} junto. Ative “Esforço por série” nas Configurações para ver.',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'O RIR conta as repetições que ainda ficaram no tanque; o RPE mede o mesmo esforço numa escala de 10, então RPE ≈ 10 − RIR. Escolha a que você já usa de cabeça.',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': 'A linha destacada é onde cai a maioria das séries de trabalho. As séries já registradas mantêm a escala delas, e nada mais usa esse valor, então a progressão e o 1RM estimado não mudam.',
  'No weight to enter. Just log the reps.': 'Sem peso para informar. É só registrar as repetições.',
  'Reps climb by one whenever every set was clean. Set a ceiling to add sets instead of reps forever.': 'As repetições aumentam em uma quando todas as séries são concluídas. Defina um limite para adicionar séries em vez de aumentar repetições indefinidamente.',
  '{0} reps in every set! Add a set and go back to {1}.': '{0} repetições em todas as séries! Adicione uma série e volte para {1}.',
  'You still log the total: {0} is {1} per side.': 'Você ainda registra o total: {0} corresponde a {1} de cada lado.',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': 'Duas séries normais e uma série final até a falha. Supere a meta nessa série e o peso sobe (em dobro se você dobrar as repetições). Uma falha reduz 10 %.',
  'Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.': 'As repetições aumentam até {0}; depois, uma série é adicionada e as repetições recomeçam. Ao chegar a {1} séries, o app sugere adicionar peso.',

