  // --- more passkeys, one-time codes for another device (#95) ---
  '1 passkey': '1 chave de acesso',
  'A one-time code lets your phone or another computer sign in with a passkey of its own.': 'Um código de uso único permite que seu celular ou outro computador entre com uma chave de acesso própria.',
  'Add a passkey': 'Adicionar uma chave de acesso',
  'Add another device': 'Adicionar outro dispositivo',
  'Add this device': 'Adicionar este dispositivo',
  'Added {0}': 'Adicionada em {0}',
  'Code from your other device': 'Código do seu outro dispositivo',
  'Confirm with a passkey': 'Confirmar com uma chave de acesso',
  'Confirmed. Now create the new passkey; your browser will ask where to keep it.': 'Confirmado. Agora crie a nova chave de acesso; seu navegador vai perguntar onde guardá-la.',
  'Copy link': 'Copiar link',
  'Create a passkey on this device for the profile “{0}”. It signs you in here from now on.': 'Crie neste dispositivo uma chave de acesso para o perfil “{0}”. A partir de agora, você entra aqui com ela.',
  'Each one signs in to this profile from the device or password manager that keeps it. Tap one to rename or remove it.': 'Cada uma entra neste perfil a partir do dispositivo ou do gerenciador de senhas que a guarda. Toque em uma para renomeá-la ou removê-la.',
  'Enter the code from your other device.': 'Digite o código do seu outro dispositivo.',
  'For this device, a security key, a password manager, or your phone through the browser’s own QR code. First confirm that it is you.': 'Para este dispositivo, uma chave de segurança, um gerenciador de senhas ou seu celular pelo código QR do próprio navegador. Primeiro confirme que é você.',
  'It can no longer sign in to this profile. A device already signed in with it stays signed in. If it was lost, use Sign out everywhere.': 'Ela não poderá mais entrar neste perfil. Um dispositivo que já entrou com ela continua conectado. Se ele foi perdido, use “Sair de todos os dispositivos”.',
  'It is your only way in, so it cannot be removed until there is another.': 'É sua única forma de entrar, por isso não pode ser removida enquanto não houver outra.',
  'Last used {0}': 'Usada pela última vez em {0}',
  'Make a new code': 'Criar um novo código',
  'Name, e.g. Work laptop': 'Nome, ex.: Notebook do trabalho',
  'None yet. Add one and sign in without your password.': 'Nenhuma ainda. Adicione uma e entre sem sua senha.',
  'Passkey added': 'Chave de acesso adicionada',
  'Passkey removed': 'Chave de acesso removida',
  'Passkey {0}': 'Chave de acesso {0}',
  'Passkeys': 'Chaves de acesso',
  'Remove passkey': 'Remover chave de acesso',
  'Remove this passkey?': 'Remover esta chave de acesso?',
  'Scan this with the other device, or open openGym there and enter the code on the sign-in screen. It works once, for {0} minutes.': 'Escaneie isto com o outro dispositivo, ou abra o openGym nele e digite o código na tela de entrada. Funciona uma vez, por {0} minutos.',
  'That code is wrong, already used or expired. Make a new one on your other device.': 'Esse código está errado, já foi usado ou expirou. Crie um novo no seu outro dispositivo.',
  'This browser cannot confirm with your passkey. Do this on a device that holds one.': 'Este navegador não consegue confirmar com sua chave de acesso. Faça isso em um dispositivo que tenha uma.',
  'First confirm that it is you.': 'Primeiro confirme que é você.',
  'This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.': 'Este perfil não tem nenhuma chave de acesso e este servidor não aceita senhas, então nada aqui pode confirmar que é você. Fale com seu administrador.',
  'This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.': 'Este navegador não consegue criar chaves de acesso, por isso não pode ser adicionado com um código. Abra o link em um navegador que consiga.',
  'This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.': 'Este navegador está conectado como “{0}”. Adicioná-lo a “{1}” desconecta “{0}” aqui.',
  'This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.': 'Este código é de outro perfil que também se chama “{0}”, não daquele com que este navegador está conectado. Adicionar o navegador lá desconecta o seu perfil aqui.',
  'Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.': 'Continue só se este código vier de um dispositivo seu. Este navegador fica então conectado a “{0}”, e o que você registrar aqui vai para esse perfil.',
  'This code has expired.': 'Este código expirou.',
  'This device already has a passkey for this profile.': 'Este dispositivo já tem uma chave de acesso para este perfil.',
  'This passkey already belongs to a profile.': 'Esta chave de acesso já pertence a um perfil.',
  'This profile already has as many passkeys as it can hold.': 'Este perfil já tem todas as chaves de acesso que pode ter.',
  'Use a code from your other device': 'Usar um código do seu outro dispositivo',
  'You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.': 'Você recebe um código com o qual seu celular ou outro computador pode criar uma chave de acesso para este perfil. Primeiro confirme que é você.',
  'or with your password': 'ou com sua senha',
