  'Most of the work got done. One or two sets fell short, which is fine once. It only becomes a signal if the same sets miss next time.': 'A maior parte do trabalho foi feita. Uma ou duas séries ficaram aquém, e uma vez tudo bem. Só vira sinal se as mesmas séries falharem da próxima vez.',
