  'The server cannot be reached': 'Não é possível acessar o servidor',
  'Your server can’t be reached. Your changes are saved on this device and sync once it answers again.': 'Não é possível acessar o seu servidor. Suas alterações ficam salvas neste dispositivo e sincronizam assim que ele voltar a responder.',
  'Your server can’t be reached. Showing the last copy synced with it.': 'Não é possível acessar o seu servidor. Mostrando a última cópia sincronizada com ele.',
  'Pair again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Pareie de novo ou exporte um backup antes. Se continuar mesmo assim, uma cópia dessas alterações fica neste dispositivo até ele se conectar de novo a este servidor com esta conta. Aí elas são adicionadas de volta.',
  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': 'Entre de novo ou exporte um backup antes. Se continuar mesmo assim, uma cópia dessas alterações fica neste dispositivo até ele se conectar de novo a este servidor com esta conta. Aí elas são adicionadas de volta.',
  'No sets are left in this workout, so there is nothing to save. Delete it from your history?': 'Não sobrou nenhuma série neste treino, então não há nada para salvar. Excluí-lo do seu histórico?',
  // --- a custom exercise's own photo, GIF or video, and its link ---
  'Photo, GIF or video': 'Foto, GIF ou vídeo',
  'Optional. A picture makes it easier to spot in a list.': 'Opcional. Com uma imagem fica mais fácil achar na lista.',
  'Add': 'Adicionar',
  'Change': 'Alterar',
  'Video or guide link (optional)': 'Link de um vídeo ou guia (opcional)',
  'That link is not a web address': 'Esse link não é um endereço da web',
  'Watch video': 'Assistir ao vídeo',
  'Open link': 'Abrir link',
  'Plays from YouTube, and only once you tap': 'Reproduz a partir do YouTube, e só quando você toca',
  'Opens in YouTube': 'Abre no YouTube',
  'That file type isn’t supported. Use a photo, a GIF, or an MP4, MOV or WebM video.': 'Esse tipo de arquivo não é compatível. Use uma foto, um GIF, ou um vídeo MP4, MOV ou WebM.',
  'That file is too big. Max {0} MB.': 'Esse arquivo é grande demais. Máximo de {0} MB.',
  'That video is too long. Max {0} seconds.': 'Esse vídeo é longo demais. Máximo de {0} segundos.',
  'That photo is too large to process on this device.': 'Essa foto é grande demais para ser processada neste dispositivo.',
  'You’re offline. Try again once you’re back online.': 'Você está offline. Tente de novo quando a conexão voltar.',
  'This browser cannot read that file.': 'Este navegador não consegue ler esse arquivo.',
  'There is no room left on this device for that file.': 'Não há mais espaço neste dispositivo para esse arquivo.',
  'This video may not play on every device. MP4 (H.264) plays everywhere.': 'Este vídeo pode não rodar em todos os dispositivos. MP4 (H.264) roda em qualquer lugar.',
  'Your photo and video space on the server is full ({0} of {1} MB).': 'Seu espaço para fotos e vídeos no servidor está cheio ({0} de {1} MB).',
  'The server refused the file as too large.': 'O servidor recusou o arquivo por ser grande demais.',
  'Kept on this device only. Export with photos & videos keeps a copy.': 'Salvo só neste dispositivo. Exportar com fotos e vídeos guarda uma cópia.',
  'Your server does not store photos and videos yet.': 'Seu servidor ainda não armazena fotos e vídeos.',
  'This browser cannot store photos or videos here.': 'Este navegador não consegue armazenar fotos ou vídeos aqui.',
  'Photos & videos': 'Fotos e vídeos',
  '{0} of {1} MB used on your server': '{0} de {1} MB usados no seu servidor',
  '{0} waiting to upload': '{0} aguardando envio',
