  // --- AI Coach: why a job failed or was refused (lib/coach-api.js JOB_ERRORS, BYOK_ERRORS) ---
  'The Coach is taking a rest day. Try again tomorrow.': 'O Treinador tirou o dia de descanso. Tente de novo amanhã.',
  'The Coach took too long and gave up.': 'O Treinador demorou demais e desistiu.',
  'The Coach couldn’t sign in to its provider. The instance owner needs to check its setup.': 'O Treinador não conseguiu fazer login no provedor. O proprietário da instância precisa verificar a configuração.',
  'The Coach couldn’t run. The instance owner needs to check its setup.': 'O Treinador não conseguiu rodar. O proprietário da instância precisa verificar a configuração.',
  'The Coach hit its AI provider’s limit. Try again later, or the instance owner needs to check the plan or key.': 'O Treinador chegou ao limite do provedor de IA. Tente mais tarde, ou o proprietário da instância precisa verificar o plano ou a chave.',
  'The Coach’s AI provider rejected the request format. The instance owner needs to try another model.': 'O provedor de IA do Treinador recusou o formato da solicitação. O proprietário da instância precisa testar outro modelo.',
  'The Coach’s AI provider is having an outage. Try again in a little while.': 'O provedor de IA do Treinador está fora do ar. Tente de novo daqui a pouco.',
  'The Coach couldn’t reach its AI provider. The instance owner needs to check the endpoint and the network.': 'O Treinador não conseguiu falar com o provedor de IA. O proprietário da instância precisa verificar o endpoint e a rede.',
  'The Coach answered with something the app couldn’t use.': 'O Treinador respondeu com algo que o app não consegue usar.',
