  "Challenge done: {0}. New badge!": "Desafio concluído: {0}. Nova medalha!",
  "Hide until next month": "Ocultar até o próximo mês",
  "Gold month. Take a bow.": "Mês de ouro. Pode agradecer os aplausos.",
  "Every challenge you finish puts a badge here, one shelf per month.": "Cada desafio concluído deixa uma medalha aqui, uma prateleira por mês.",
  "Three goals a month on Home, sized to how you train.": "Três metas por mês no Início, sob medida para você.",
  // --- v1.4.4: LAN http for the phone Coach (#913), freestyle progression (#910), watch idle finish (#904) ---
  "Plain http:// only works for an address on your home network, like 192.168.x.x, a .local name or a Tailscale 100.x address. Anything on the internet needs https://.": "O http:// sem criptografia só funciona para um endereço da sua rede de casa, como 192.168.x.x, um nome .local ou um endereço 100.x do Tailscale. Tudo o que está na internet precisa de https://.",
  "Plain http only on your home network": "http sem criptografia só na rede de casa",
  "Freestyle repeats what you did last time, with no progression rule. Rules apply to exercises in a routine.": "O treino livre repete o que você fez da última vez, sem regra de progressão. As regras valem para os exercícios de uma rotina.",
  "Your watch thought this workout was forgotten. It keeps going here.": "Seu relógio achou que este treino tinha sido esquecido. Aqui ele continua.",
  "No rule (freestyle)": "Sem regra (livre)",
  "Freestyle keeps the numbers you set. A rule picked here applies to this workout only.": "O treino livre mantém os números que você definir. Uma regra escolhida aqui só vale para este treino.",
  // --- v1.4.5: warm-ups and the Coach mid-workout, in Brazilian wording ---
  "Built from your work weight and rounded to this gym’s plates and dumbbells. An exercise can pick its own in its settings.": "Calculados a partir do peso de trabalho e arredondados às anilhas e halteres desta academia. Cada exercício pode escolher os seus nas configurações.",
  "Follows Settings → Workout → Automatic warm-ups.": "Segue Configurações → Treino → Aquecimentos automáticos.",
  "It pinches, so lighter for the rest of it. Stop if it still hurts.": "Está incomodando, então mais leve no que falta. Pare se continuar doendo.",
  "Logged sets and your routine stay as they are. The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.": "As séries registradas e sua rotina continuam como estão. O Treinador não é médico nem fisioterapeuta. Se algo doer, procure um profissional.",
  "Looking at your workout…": "Olhando seu treino…",
  "Nothing to change. Carry on as planned.": "Nada a mudar. Siga como planejado.",
  "Routines, exercises, sets and reps, warm-ups, programmes, your weekly schedule, progression settings and what your gym can load.": "Rotinas, exercícios, séries e repetições, aquecimentos, programas, sua agenda semanal, configurações de progressão e o que sua academia consegue carregar.",
  "Saved under Plan → Programmes. It starts when you start it.": "Salvo em Plano → Programas. Começa quando você iniciar.",
  "The app ramps up from your work weight: more warm-up sets when it is heavy, fewer when it is light, on your gym’s plates.": "O app sobe a partir do peso de trabalho: mais aquecimentos quando é pesado, menos quando é leve, com as anilhas da sua academia.",
  "The rack is taken, so do it at the end. The rest of the session does not need it.": "O rack está ocupado, então faça no fim. O resto do treino não precisa dele.",
  "This is the demo, so there is no AI model behind me. On your own server I read your session and suggest changes like these.": "Isto é a demo, então não tem modelo de IA por trás. No seu próprio servidor eu leio o treino e sugiro mudanças como estas.",
  "What’s up? The Coach suggests a few changes to what is left of this workout. Logged sets stay as they are.": "E aí, o que houve? O Treinador sugere algumas mudanças para o que falta do treino. As séries registradas ficam como estão.",
  "You can keep training, the answer waits here and in the Coach.": "Você pode continuar treinando, a resposta espera aqui e no Treinador.",
  "You feel strong, so a little more on the bar for what is left. Not a new max, just a nudge.": "Você está forte, então um pouco mais na barra no que falta. Não é um novo máximo, só um empurrão.",
  "Only the warm-ups you plan yourself.": "Só os aquecimentos que você mesmo planeja.",
  "Keep these warm-ups": "Salvar estes aquecimentos",
  "Kept. Same warm-ups next time, scaled to your work weight.": "Salvo. Os mesmos aquecimentos na próxima vez, na escala do peso de trabalho.",
  "Saved in the routine, scaled to your work weight": "Salvo na rotina, na escala do peso de trabalho",
  "Your rows, as a share of the work weight, so they grow with it.": "Suas linhas, como parte do peso de trabalho, então crescem com ele.",
  "Nothing could be applied any more.": "Não deu mais para aplicar nada.",
  "That workout is over, so these can’t be applied any more.": "Esse treino já acabou, então não dá mais para aplicar.",
  "Your workout moved on, so this one no longer fits.": "Seu treino avançou, então esta não encaixa mais.",
  "There’s no workout running.": "Não tem nenhum treino rolando.",
  "Squats, presses, rows and friends get a ramp. Curls and raises start cold.": 'Agachamentos, supinos, remadas e afins ganham séries de aproximação. Roscas e elevações começam direto.',
