  "{0} sees only what is on here.": "{0} vê só o que está ligado aqui.",
  "You are letting this trainer see the categories marked here, and change the ones marked suggest or apply. If the trainer works for a gym, its gym lead sees the categories in the gym lead row, never more than view. You can change this or disconnect any time, and it stops working the moment you do. Every look and every change is written to your sharing log, which only you can read.": "Você deixa este treinador ver as categorias marcadas aqui e alterar as marcadas como sugerir ou aplicar. Se o treinador trabalha para uma academia, o responsável dela vê as categorias da linha dele, nunca mais do que ver. Você pode mudar isso ou se desconectar quando quiser, e para de funcionar no momento em que fizer isso. Cada olhada e cada alteração fica no seu registro de compartilhamento, que só você pode ler.",
  "A word with it (optional)": "Umas palavras junto (opcional)",
