  "This is public to everyone on this server: everyone with an account here can see it, try it and copy it. Your name and the date go with it, always. Only share what is yours: something you made, recorded or have the right to pass on. The exercise pictures and animations of the built-in library are licensed and can never be shared. You can stop sharing any time; copies people already took stay with them.": "Isto é público para todo mundo neste servidor: qualquer pessoa com conta aqui pode ver, testar e copiar. Seu nome e a data vão sempre junto. Compartilhe só o que é seu: algo que você fez, gravou ou tem o direito de repassar. As imagens e animações de exercícios da biblioteca integrada são licenciadas e nunca podem ser compartilhadas. Você pode parar de compartilhar quando quiser; as cópias que outras pessoas já pegaram ficam com elas.",
