  "Steady double progression": "Dupla progressão constante",
  "Undulating days": "Dias ondulantes",
  "Shorter rests": "Descansos mais curtos",
  "Work up a rep range one rep at a time. Every set has to hit the target before it moves, and at the top of the range the weight goes up.": "Suba por uma faixa de repetições, uma de cada vez. Todas as séries precisam chegar ao objetivo antes de ele subir, e no topo da faixa o peso sobe.",
  "Each session rotates: a medium day at your reps, a heavy day with fewer, a light day with more. The weights come from your estimated max, so they climb as you get stronger.": "Cada sessão alterna: um dia médio com as suas repetições, um dia pesado com menos e um leve com mais. Os pesos vêm do seu máximo estimado, então sobem conforme você fica mais forte.",
  "Same weight, a bit less rest each time every set is clean. At your shortest rest the weight goes up and the rest starts over.": "Mesmo peso, um pouco menos de descanso toda vez que todas as séries saem limpas. No descanso mais curto o peso sobe e o descanso recomeça.",
  "Every set hit {0}. Same weight, {1} reps this time.": "Todas as séries chegaram a {0}. Mesmo peso, {1} repetições desta vez.",
  "Not every set reached {0} yet. Same weight and target again ({1} of {2} to go).": "Nem todas as séries chegaram a {0} ainda. Mesmo peso e objetivo de novo (faltam {1} de {2}).",
  "Every set clean. Same weight with {0}s less rest: {1}s.": "Todas as séries limpas. Mesmo peso com {0} s a menos de descanso: {1} s.",
  "Clean at your shortest rest. {0} {1} less help, rest back to {2}s.": "Limpo no descanso mais curto. {0} {1} a menos de ajuda, descanso de volta a {2} s.",
  "Clean at your shortest rest. {0} {1} more, rest back to {2}s.": "Limpo no descanso mais curto. {0} {1} a mais, descanso de volta a {2} s.",
  "Stuck for {0} sessions. Same weight with more rest: {1}s.": "Travado há {0} sessões. Mesmo peso com mais descanso: {1} s.",
  "Missed reps last time. Same weight and rest again ({0} of {1} to go).": "Você errou repetições da última vez. Mesmo peso e descanso de novo (faltam {0} de {1}).",
  "Heavy day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Dia pesado: {0} repetições com {1} {2}, a partir do seu máximo estimado de {3} {2}.",
  "Light day: {0} reps at {1} {2}, from your estimated max of {3} {2}.": "Dia leve: {0} repetições com {1} {2}, a partir do seu máximo estimado de {3} {2}.",
